def sort_list(arr: list[int]) -> list[int]:
    """Sort a list of integers in ascending order. Must be stable."""
    result = list(arr)
    n = len(result)
    if n <= 1:
        return result
    # Fast path: already sorted
    already_sorted = True
    for i in range(n - 1):
        if result[i] > result[i + 1]:
            already_sorted = False
            break
    if already_sorted:
        return result

    def merge(left: list[int], right: list[int]) -> list[int]:
        merged: list[int] = []
        i = j = 0
        len_l = len(left)
        len_r = len(right)
        while i < len_l and j < len_r:
            # <= ensures stability: take from left on equality
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        if i < len_l:
            merged.extend(left[i:])
        if j < len_r:
            merged.extend(right[j:])
        return merged

    def merge_sort(a: list[int]) -> list[int]:
        m = len(a)
        if m <= 1:
            return a
        # Optimization: insertion sort for small runs (stable)
        if m <= 16:
            for i in range(1, m):
                key = a[i]
                j = i - 1
                while j >= 0 and a[j] > key:
                    a[j + 1] = a[j]
                    j -= 1
                a[j + 1] = key
            return a
        mid = m // 2
        left = merge_sort(a[:mid])
        right = merge_sort(a[mid:])
        return merge(left, right)

    return merge_sort(result)
